from docx import Document
from docx.shared import Pt, Cm
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.enum.table import WD_TABLE_ALIGNMENT
from docx.oxml import OxmlElement
from docx.oxml.ns import qn
from pathlib import Path

OUT=Path('output'); OUT.mkdir(exist_ok=True)

def setup(d):
    s=d.sections[0]; s.top_margin=Cm(1.5); s.bottom_margin=Cm(1.5); s.left_margin=Cm(2); s.right_margin=Cm(1.5)
    st=d.styles['Normal']; st.font.name='Arial'; st._element.rPr.rFonts.set(qn('w:eastAsia'),'Arial'); st.font.size=Pt(9)
    p=d.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER
    return d
def title(d,t):
    p=d.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; r=p.add_run(t); r.bold=True; r.font.size=Pt(14)
def para(d,t,bold=False):
    p=d.add_paragraph(); r=p.add_run(t); r.bold=bold; return p
def kv(d, rows):
    tab=d.add_table(rows=0, cols=2); tab.alignment=WD_TABLE_ALIGNMENT.CENTER; tab.style='Table Grid'
    for a,b in rows:
        c=tab.add_row().cells; c[0].text=a; c[1].text=b
    return tab

